ALTER TABLE customer ADD COLUMN IF NOT EXISTS user_id uuid REFERENCES app_user(id);
ALTER TABLE merchant ADD COLUMN IF NOT EXISTS slug text;
CREATE UNIQUE INDEX IF NOT EXISTS merchant_tenant_slug_idx ON merchant(tenant_id,slug) WHERE slug IS NOT NULL;
CREATE INDEX IF NOT EXISTS customer_user_tenant_idx ON customer(user_id,tenant_id);
CREATE TABLE IF NOT EXISTS marketplace_category (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, description text, icon_key text, regulated boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS merchant_category (merchant_id uuid NOT NULL REFERENCES merchant(id), category_id uuid NOT NULL REFERENCES marketplace_category(id), PRIMARY KEY(merchant_id,category_id));
CREATE TABLE IF NOT EXISTS merchant_hours (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), merchant_id uuid NOT NULL REFERENCES merchant(id), day_of_week smallint NOT NULL CHECK(day_of_week BETWEEN 0 AND 6), opens_at time, closes_at time, closed boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), merchant_id uuid NOT NULL REFERENCES merchant(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS catalog_category (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), catalog_id uuid NOT NULL REFERENCES catalog(id), name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS catalog_product (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), catalog_id uuid NOT NULL REFERENCES catalog(id), category_id uuid REFERENCES catalog_category(id), name text NOT NULL, slug text NOT NULL, description text, image_ref text, sku text, upc text, price_cents bigint NOT NULL CHECK(price_cents >= 0), sale_price_cents bigint CHECK(sale_price_cents IS NULL OR sale_price_cents >= 0), tax_class text, age_restricted boolean NOT NULL DEFAULT false, inventory_count integer, available boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(catalog_id,slug));
CREATE INDEX IF NOT EXISTS catalog_product_search_idx ON catalog_product(tenant_id,catalog_id,available);
CREATE TABLE IF NOT EXISTS catalog_modifier_group (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), product_id uuid NOT NULL REFERENCES catalog_product(id), name text NOT NULL, required boolean NOT NULL DEFAULT false, min_selections integer NOT NULL DEFAULT 0, max_selections integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS catalog_modifier_option (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), group_id uuid NOT NULL REFERENCES catalog_modifier_group(id), name text NOT NULL, price_adjustment_cents bigint NOT NULL DEFAULT 0, available boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS customer_address (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), customer_id uuid NOT NULL REFERENCES customer(id), label text, address jsonb NOT NULL, latitude numeric(9,6), longitude numeric(9,6), delivery_instructions text, access_notes text, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cart (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), customer_user_id uuid NOT NULL REFERENCES app_user(id), merchant_id uuid NOT NULL REFERENCES merchant(id), address_id uuid REFERENCES customer_address(id), status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','CHECKED_OUT','ABANDONED')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_user_id,merchant_id,status));
CREATE TABLE IF NOT EXISTS cart_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), cart_id uuid NOT NULL REFERENCES cart(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES catalog_product(id), quantity integer NOT NULL CHECK(quantity > 0), unit_price_cents bigint NOT NULL CHECK(unit_price_cents >= 0), modifiers jsonb NOT NULL DEFAULT '[]', special_instructions text, UNIQUE(cart_id,product_id,modifiers));
ALTER TABLE cart_item ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS commerce_order (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), customer_user_id uuid NOT NULL REFERENCES app_user(id), merchant_id uuid NOT NULL REFERENCES merchant(id), cart_id uuid REFERENCES cart(id), delivery_id uuid REFERENCES delivery(id), status text NOT NULL DEFAULT 'ORDER_PLACED' CHECK(status IN ('ORDER_PLACED','MERCHANT_CONFIRMED','PREPARING','READY','COURIER_ASSIGNED','COURIER_ARRIVING_PICKUP','PICKED_UP','ON_THE_WAY','ARRIVING','VERIFICATION_REQUIRED','DELIVERED','CANCELED','RETURNING','RETURNED')), fulfillment_mode text NOT NULL DEFAULT 'DELIVERY' CHECK(fulfillment_mode IN ('DELIVERY','PICKUP')), delivery_address jsonb, delivery_instructions text, item_subtotal_cents bigint NOT NULL DEFAULT 0, tax_cents bigint NOT NULL DEFAULT 0, delivery_fee_cents bigint NOT NULL DEFAULT 0, service_fee_cents bigint NOT NULL DEFAULT 0, tip_cents bigint NOT NULL DEFAULT 0, discount_cents bigint NOT NULL DEFAULT 0, total_cents bigint NOT NULL DEFAULT 0, currency char(3) NOT NULL DEFAULT 'USD', scheduled_for timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS commerce_order_customer_idx ON commerce_order(tenant_id,customer_user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS commerce_order_item (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), order_id uuid NOT NULL REFERENCES commerce_order(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES catalog_product(id), product_name text NOT NULL, quantity integer NOT NULL, unit_price_cents bigint NOT NULL, modifiers jsonb NOT NULL DEFAULT '[]', special_instructions text);
CREATE TABLE IF NOT EXISTS commerce_order_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), order_id uuid NOT NULL REFERENCES commerce_order(id), previous_status text, status text NOT NULL, actor_id uuid, reason text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO marketplace_category(slug,name,description,icon_key,sort_order) VALUES ('restaurants','Restaurants','Local favorites and comfort food','food',1),('convenience','Convenience','Everyday essentials, delivered','bag',2),('grocery','Grocery','Fresh essentials, nearby','grocery',3),('retail','Retail','Neighborhood shops and finds','spark',4),('flowers-gifts','Flowers & Gifts','Something thoughtful, right on time','gift',5),('pharmacy-otc','Pharmacy / OTC','Everyday wellness essentials','health',6),('pet','Pet','For the companions at home','paw',7),('electronics','Electronics','Useful tech from local shops','bolt',8),('beauty','Beauty','Self-care from nearby','beauty',9),('local-shops','Local Shops','The good stuff close to home','local',10) ON CONFLICT(slug) DO NOTHING;
